	public void CandidateWindowKeepsAllPinnedNativeProtocols( string hex, int mode, bool anchored, bool endAnchored, bool firstLine, string protocols ) {
		var source = Convert.FromHexString( hex );
		var cases = protocols.Split( ';' ).Select( Protocol.Parse ).ToArray();
		var reference = Reference( source, mode, anchored, endAnchored, firstLine );
		// Validate every native outcome before a missing managed policy can stop the batch.
		foreach ( var item in cases ) { AssertNative( reference, item.Subject, item.Offset, item.Spans, item.Mark ); }
		var compiled = Compile( source, Options( mode, anchored, endAnchored, firstLine ) );
		foreach ( var item in cases ) {
			Compare( reference, item.Subject, item.Offset, compiled.Match( item.Subject, item.Offset ), $"{hex}/{mode}/{Convert.ToHexString( item.Subject )}/{item.Offset}" );
		}
	}

