	public void FirstLinePreservesCompileDiagnosticsAndOriginalOffsets( string hex, int mode, bool anchored, bool endAnchored, int nativeCode, int nativeOffset, string code, int offset ) {
		var source = Convert.FromHexString( hex );
		var native = Assert.Throws<PcrePatternException>( () => Reference( source, mode, anchored, endAnchored ) );
		Assert.Equal( nativeCode, (int)native.ErrorCode );
		Assert.EndsWith( $" at offset {nativeOffset}.", native.Message );
		var actual = PcreByteCompiler.Compile( source, Options( mode, anchored, endAnchored ) );
		Assert.Null( actual.Pattern );
		Assert.Equal( Enum.Parse<PcreByteDiagnosticCode>( code ), actual.Diagnostic?.Code );
		Assert.Equal( offset, actual.Diagnostic?.ByteOffset );
	}

	[Theory]
	[InlineData( "A", "410A42", 0, 0, "0:1", "" )]
	[InlineData( "(A)\\1", "41410A42", 0, 0, "0:2,0:1", "" )]
	[InlineData( "A(?R)?B", "414142420A", 1, 0, "0:4", "" )]
	[InlineData( "A\\n\\KB", "410A42", 1, 0, "2:1", "" )]
	[InlineData( "A.B", "412E420A", 17, 0, "0:3", "" )]
	[InlineData( "I", "C4B10A49", 4105, 0, "0:2", "" )]
	[InlineData( "A", "20410A", 65, 1, "1:1", "" )]
	[InlineData( "A", "410D0A", 385, 0, "0:1", "" )]
	[InlineData( "A(*ACCEPT)B", "410A42", 0, 0, "0:1", "" )]
	public void FirstSuccessfulAttemptSharesWorkLimitsAndCancellation( string pattern, string hex, int mode, int offset, string spans, string mark ) {
		var source = Encoding.UTF8.GetBytes( pattern );
		var subject = Convert.FromHexString( hex );
		var reference = Reference( source, mode );
		AssertNative( reference, subject, offset, spans, mark );
		AssertNative( Reference( source, mode, firstLine: false ), subject, offset, spans, mark );
		var steps = new List<int>();
		var ordinarySteps = new List<int>();
		Compare( reference, subject, offset, Compile( source, Options( mode ) with { WorkObserver = steps.Add } ).Match( subject, offset ), pattern );
		Compare( reference, subject, offset, Compile( source, Options( mode, firstLine: false ) with { WorkObserver = ordinarySteps.Add } ).Match( subject, offset ), pattern );
		Assert.Equal( ordinarySteps, steps );
		Assert.Equal( Enumerable.Range( 1, steps.Count ), steps );
		Assert.True( steps.Count > 2 );
		Compare( reference, subject, offset, Compile( source, Options( mode ) with { MatchWorkLimit = steps.Count } ).Match( subject, offset ), "exact work" );
		var limited = Compile( source, Options( mode ) with { MatchWorkLimit = steps.Count - 1 } ).Match( subject, offset );
		Assert.Null( limited.Match );
		Assert.Equal( PcreByteDiagnosticCode.MatchWorkLimitExceeded, limited.Diagnostic?.Code );
		using var cancellation = new CancellationTokenSource();
		var cancellable = Compile( source, Options( mode ) with {
			WorkObserver = count => { if ( count == 2 ) { cancellation.Cancel(); } }
		} );
		Assert.Throws<OperationCanceledException>( () => cancellable.Match( subject, offset, cancellation.Token ) );
		Assert.Throws<OperationCanceledException>( () => PcreByteCompiler.Compile( source, Options( mode ) with { MatchWorkLimit = 0 }, cancellation.Token ) );
		Assert.Equal( PcreByteDiagnosticCode.InvalidWorkLimit, PcreByteCompiler.Compile( new byte[] { 0xFF }, Options( mode ) with { MatchWorkLimit = 0 } ).Diagnostic?.Code );
	}

	[Theory]
	[InlineData( false )]
	[InlineData( true )]
	public void FailedByteSearchStopsSpendingWorkAtTheInitialNewline( bool observed ) {
		var source = "A"u8.ToArray();
		var subject = Encoding.ASCII.GetBytes( String.Concat( "\n", new string( 'B', 20000 ) ) );
		AssertNative( Reference( source, 0 ), subject, 0, "", "" );
		var steps = new List<int>();
		var options = Options( 0 ) with { MatchWorkLimit = 4, WorkObserver = observed ? steps.Add : null };
		var actual = Compile( source, options ).Match( subject );
		Assert.True( actual.IsSuccess, actual.Diagnostic?.Message );
		Assert.Null( actual.Match );
		if ( observed ) { Assert.Equal( new[] { 1, 2, 3, 4 }, steps ); }
		var limited = Compile( source, options with { MatchWorkLimit = 3 } ).Match( subject );
		Assert.Null( limited.Match );
		Assert.Equal( PcreByteDiagnosticCode.MatchWorkLimitExceeded, limited.Diagnostic?.Code );
	}

	[Fact]
	public void CompiledWindowAndOwnedLabelsSurviveCallerMutation() {
		var source = "(*MARK:N)(A)"u8.ToArray();
		var reference = Reference( source, 0 );
		AssertNative( reference, "B\nA"u8.ToArray(), 0, "", "" );
		AssertNative( reference, "BA\n"u8.ToArray(), 0, "1:1,1:1", "4E" );
		var options = Options( 0 );
		var compiled = Compile( source, options );
		Array.Fill( source, (byte)'x' );
		typeof( PcreByteOptions ).GetProperty( "FirstLine" )?.SetValue( options, false );
		Compare( reference, "B\nA"u8.ToArray(), 0, compiled.Match( "B\nA"u8.ToArray() ), "owned window" );
		Compare( reference, "BA\n"u8.ToArray(), 0, compiled.Match( "BA\n"u8.ToArray() ), "owned source and label" );
	}

	[Theory]
	[InlineData( 1 )]
	[InlineData( 9 )]
	[InlineData( 17 )]
	public void SubjectAndOffsetValidationStillPrecedesWindowRejection( int mode ) {
		var source = "A"u8.ToArray();
		var reference = Reference( source, mode );
		AssertNative( reference, "éA"u8.ToArray(), 2, "2:1", "" );
		var compiled = Compile( source, Options( mode ) );
		foreach ( var item in new[] { ( Hex: "0AFF42", Offset: 1 ), ( Hex: "420AFF", Offset: 2 ) } ) {
			var actual = compiled.Match( Convert.FromHexString( item.Hex ) );
			Assert.Null( actual.Match );
			Assert.Equal( PcreByteDiagnosticCode.InvalidUtf8Subject, actual.Diagnostic?.Code );
			Assert.Equal( item.Offset, actual.Diagnostic?.ByteOffset );
		}
		var split = compiled.Match( "éA"u8.ToArray(), 1 );
		Assert.Null( split.Match );
		Assert.Equal( PcreByteDiagnosticCode.InvalidStartOffset, split.Diagnostic?.Code );
		foreach ( var offset in new[] { -1, 4 } ) {
			var outside = compiled.Match( new byte[] { 0xFF }, offset );
			Assert.Null( outside.Match );
			Assert.Equal( PcreByteDiagnosticCode.InvalidStartOffset, outside.Diagnostic?.Code );
		}
	}

	[Theory]
	[InlineData( 0 )]
	[InlineData( 1 )]
	[InlineData( 2 )]
	public void FirstLineDoesNotConsumeCaptureDepthOrInstructionCapacity( int selection ) {
		var pattern = selection switch {
			0 => new string( 'A', 4095 ),
			1 => String.Concat( String.Concat( Enumerable.Repeat( "()", 256 ) ), "A" ),
			_ => String.Concat( String.Concat( Enumerable.Repeat( "(?:", 256 ) ), "A", new string( ')', 256 ) )
		};
		var mode = selection == 0 ? 16 : 1;
		var source = Encoding.UTF8.GetBytes( pattern );
		var subject = selection == 0 ? Encoding.ASCII.GetBytes( String.Concat( pattern, "\nB" ) ) : "A\n"u8.ToArray();
		var spans = selection == 0 ? "0:4095" : selection == 1 ? String.Concat( "0:1,", String.Join( ",", Enumerable.Repeat( "0:0", 256 ) ) ) : "0:1";
		var reference = Reference( source, mode, anchored: true );
		AssertNative( reference, subject, 0, spans, "" );
		Compare( reference, subject, 0, Compile( source, Options( mode, anchored: true ) ).Match( subject ), "shared capacity" );
	}

	[Fact]
	public void LiteralFirstLineRetainsTheSharedCompiledInstructionLimit() {
		var source = Encoding.ASCII.GetBytes( new string( 'A', 4096 ) );
		AssertNative( Reference( source, 16 ), source, 0, "0:4096", "" );
		var actual = PcreByteCompiler.Compile( source, Options( 16 ) );
		Assert.Null( actual.Pattern );
		Assert.Equal( PcreByteDiagnosticCode.PatternRepeatLimitExceeded, actual.Diagnostic?.Code );
	}

	[Fact]
	public void DefaultCompilationKeepsSearchingLaterLines() {
		var source = "A"u8.ToArray();
		var subject = "B\nA"u8.ToArray();
		var reference = Reference( source, 0, firstLine: false );
		AssertNative( reference, subject, 0, "2:1", "" );
		Compare( reference, subject, 0, Compile( source, new PcreByteOptions() ).Match( subject ), "default window" );
	}

	private readonly record struct Protocol( byte[] Subject, int Offset, string Spans, string Mark ) {
		internal static Protocol Parse( string value ) {
			var parts = value.Split( '/' );
			return new( Convert.FromHexString( parts[0] ), Int32.Parse( parts[1] ), parts[2], parts[3] );
		}
	}
	private static PcreByteOptions Options( int mode, bool anchored = false, bool endAnchored = false, bool firstLine = true ) {
		var options = new PcreByteOptions {
			Anchored = anchored, EndAnchored = endAnchored,
			Utf8 = ( mode & 1 ) != 0, Ucp = ( mode & 2 ) != 0, MatchInvalidUtf = ( mode & 4 ) != 0,
			Caseless = ( mode & 8 ) != 0, Literal = ( mode & 16 ) != 0, Multiline = ( mode & 32 ) != 0,
			MatchWord = ( mode & 64 ) != 0, MatchLine = ( mode & 128 ) != 0,
			AnyCrLfNewline = ( mode & 256 ) != 0, BsrAnyCrLf = ( mode & 512 ) != 0,
			AllowLookaroundBackslashK = ( mode & 1024 ) != 0, CaselessRestricted = ( mode & 2048 ) != 0,
			TurkishCasing = ( mode & 4096 ) != 0, DotAll = ( mode & 8192 ) != 0
		};
		// Optional for the tests-first build; native first-line expectations remain mandatory.
		typeof( PcreByteOptions ).GetProperty( "FirstLine" )?.SetValue( options, firstLine );
		return options;
	}
	private static PcreRegex8Bit Reference( byte[] source, int mode, bool anchored = false, bool endAnchored = false, bool firstLine = true ) => new( source, Encoding.UTF8, new PcreRegexSettings {
		Options = PcreOptions.Compiled | (PcreOptions)( ( anchored ? 0x80000000u : 0u ) | ( endAnchored ? 0x20000000u : 0u ) | ( firstLine ? 0x100u : 0u )
			| ( ( mode & 1 ) != 0 ? 0x80000u : 0u ) | ( ( mode & 2 ) != 0 ? 0x20000u : 0u )
			| ( ( mode & 4 ) != 0 ? 0x4000000u : 0u ) | ( ( mode & 8 ) != 0 ? 8u : 0u )
			| ( ( mode & 16 ) != 0 ? 0x2000000u : 0u ) | ( ( mode & 32 ) != 0 ? 1024u : 0u )
			| ( ( mode & 8192 ) != 0 ? 32u : 0u ) ),
		ExtraCompileOptions = (PcreExtraCompileOptions)( ( ( mode & 64 ) != 0 ? 4 : 0 ) | ( ( mode & 128 ) != 0 ? 8 : 0 )
			| ( ( mode & 1024 ) != 0 ? 64 : 0 ) | ( ( mode & 2048 ) != 0 ? 128 : 0 ) | ( ( mode & 4096 ) != 0 ? 0x10000 : 0 ) ),
		NewLine = (PcreNewLine)( ( mode & 256 ) != 0 ? 5 : 2 ),
		BackslashR = (PcreBackslashR)( ( mode & 512 ) != 0 ? 2 : 1 ), ParensLimit = 512
	} );
	private static PcreCompiledBytePattern Compile( byte[] source, PcreByteOptions options ) {
		var actual = PcreByteCompiler.Compile( source, options );
		Assert.True( actual.IsSuccess, actual.Diagnostic?.Message );
		return Assert.IsType<PcreCompiledBytePattern>( actual.Pattern );
	}
	private static void AssertNative( PcreRegex8Bit reference, byte[] subject, int offset, string spans, string mark ) {
		var match = reference.Match( subject, offset );
		Assert.Equal( spans.Length > 0, match.Success );
		if ( !match.Success ) { return; }
		Assert.Equal( mark, Convert.ToHexString( match.Mark.ToArray() ) );
		var groups = spans.Split( ',' );
		Assert.Equal( groups.Length, match.Groups.Count );
		for ( var group = 0; group < groups.Length; group++ ) {
			var capture = match.Groups[group];
			Assert.Equal( groups[group], capture.Success ? $"{capture.Index}:{capture.EndIndex - capture.Index}" : "-" );
		}
	}
	private static void Compare( PcreRegex8Bit reference, byte[] subject, int offset, PcreByteMatchResult actual, string context ) {
		var expected = reference.Match( subject, offset );
		Assert.True( actual.IsSuccess, $"{context}: {actual.Diagnostic?.Message}" );
		Assert.True( ( expected.Success ? expected.Index : -1 ) == ( actual.Match?.ByteIndex ?? -1 ), $"{context}: expected index {( expected.Success ? expected.Index : -1 )}, actual {actual.Match?.ByteIndex ?? -1}" );
		if ( !expected.Success ) { return; }
		Assert.Equal( expected.EndIndex - expected.Index, actual.Match!.ByteLength );
		Assert.Equal( expected.Mark.ToArray(), actual.Match.MarkName.ToArray() );
		Assert.Equal( expected.Groups.Count, actual.Match.Captures.Count );
		for ( var group = 0; group < expected.Groups.Count; group++ ) {
			var capture = expected.Groups[group];
			Assert.Equal( capture.Success ? new PcreByteCapture( capture.Index, capture.EndIndex - capture.Index ) : null, actual.Match.Captures[group] );
		}
	}
